"""it — sira_c."""

T = {
"sira_151": ("Quale zio del Profeta ﷺ abbracciò l'islam e fu uno dei suoi più fermi difensori alla Mecca?", ["Hamza ibn 'Abd al-Muttalib", "Abu Lahab", "Abu Talib", "Al-'Abbas"], "Hamza, zio e fratello di latte del Profeta ﷺ, abbracciò l'islam alla Mecca e fu chiamato «il leone di Allah»."),
"sira_152": ("In casa di chi si riunivano in segreto i primi musulmani alla Mecca?", ["In casa di al-Arqam", "In casa di Abu Bakr", "In casa di Khadija", "In casa di Abu Talib"], "La casa di al-Arqam ibn Abi al-Arqam, sul colle di Safa, fu il primo luogo di riunione e di insegnamento."),
"sira_153": ("Quale compagno, convertito alla Mecca, fu poi inviato come primo maestro a Yathrib?", ["Mus'ab ibn 'Umayr", "Bilal ibn Rabah", "Khalid ibn al-Walid", "Abu Hurayra"], "Mus'ab ibn 'Umayr, giovane meccano di nobile famiglia, fu inviato a Yathrib dopo il patto di 'Aqaba per insegnarvi il Corano."),
"sira_154": ("Con quale ordine comincia la sura Al-Muddaththir, che avviò l'appello pubblico?", ["«O tu che sei avvolto nel mantello! Alzati e ammonisci»", "«Leggi, in nome del tuo Signore»", "«Combatti i miscredenti»", "«Emigra a Medina»"], "«O tu che sei avvolto nel mantello! Alzati e ammonisci»."),
"sira_155": ("Quale versetto ordinò al Profeta ﷺ di proclamare apertamente ciò che gli era comandato?", ["«Proclama dunque apertamente ciò che ti è ordinato»", "«Sii paziente»", "«Recita in segreto»", "«Ritirati»"], "«Proclama dunque apertamente ciò che ti è ordinato e allontanati dagli associatori»."),
"sira_156": ("Dove affissero i Quraysh il documento del boicottaggio contro i Banu Hashim?", ["All'interno della Ka'ba", "Sulla porta della città", "Nel mercato di 'Ukaz", "Sul colle di Safa"], "Il testo del boicottaggio fu appeso dentro la Ka'ba, finché il patto fu rotto e il documento abbandonato."),
"sira_157": ("Nel giardino di chi, a Ta'if, trovò rifugio il Profeta ﷺ ricevendo un grappolo d'uva dopo essere stato cacciato?", ["Nel giardino di 'Utba e Shayba, dove lo servì lo schiavo 'Addas", "In casa del capo di Ta'if", "In una carovana di passaggio", "In casa di un fabbro"], "Ferito e cacciato da Ta'if, si rifugiò in un giardino dove gli fu offerta dell'uva, portata da uno schiavo cristiano di nome 'Addas."),
"sira_158": ("Quale compagno, dapprima feroce avversario, abbracciò l'islam e fu chiamato «colui che distingue il vero dal falso»?", ["'Umar ibn al-Khattab", "Abu Sufyan", "Khalid ibn al-Walid", "'Amr ibn al-'As"], "'Umar ibn al-Khattab, dapprima ostile, si convertì alla Mecca e ricevette il titolo di al-Faruq."),
"sira_159": ("Presso quale famiglia alloggiò il Profeta ﷺ arrivando a Medina, dove la sua cammella si inginocchiò?", ["Presso Abu Ayyub al-Ansari", "Presso Sa'd ibn Mu'adh", "Presso Ubayy ibn Ka'b", "Presso Anas ibn Malik"], "La cammella si inginocchiò presso la casa di Abu Ayyub al-Ansari, che ospitò il Profeta ﷺ al suo arrivo."),
"sira_160": ("Come si chiama il cimitero di Medina dove sono sepolti molti compagni?", ["Al-Baqi'", "Al-Mu'alla", "Al-Hijr", "Al-Quba"], "Baqi' al-Gharqad, accanto alla moschea del Profeta ﷺ, è il cimitero di Medina."),
"sira_161": ("Di quale moschea dice il Corano che fu «fondata sulla devozione fin dal primo giorno»?", ["La moschea di Quba", "La Moschea Sacra", "La moschea di Al-Aqsa", "La moschea di Kufa"], "«Una moschea fondata sulla devozione fin dal primo giorno è più degna che tu vi preghi»."),
"sira_162": ("In quale moschea pregava il Profeta ﷺ quando fu rivelato l'ordine di cambiare la qibla?", ["La moschea delle due qibla (Masjid al-Qiblatayn)", "La moschea di Quba", "La Moschea Sacra", "La moschea di Al-Aqsa"], "L'ordine giunse durante la preghiera; i fedeli si volsero verso la Ka'ba, da cui il nome «moschea delle due qibla»."),
"sira_163": ("Quale obbligo fu prescritto ai musulmani nel secondo anno dell'Egira?", ["Il digiuno del mese di Ramadan", "Il pellegrinaggio", "La preghiera notturna", "Il viaggio a Ta'if"], "Il digiuno di Ramadan divenne obbligatorio a Medina, nel secondo anno dell'Egira."),
"sira_164": ("Quale compagno vide in sogno le parole della chiamata alla preghiera, poi adottate dal Profeta ﷺ?", ["'Abdullah ibn Zayd", "Bilal ibn Rabah", "Abu Bakr", "Mu'adh ibn Jabal"], "'Abdullah ibn Zayd riferì il sogno dell'adhan; il Profeta ﷺ lo approvò e incaricò Bilal di lanciarlo."),
"sira_165": ("Che cosa dice il Corano del pugno di terra che il Profeta ﷺ lanciò a Badr?", ["«Non sei tu che hai lanciato quando hai lanciato, ma è stato Allah»", "«Hai mirato bene»", "«Il vento l'ha portata»", "«L'hanno lanciata gli angeli»"], "«E non sei tu che hai lanciato quando hai lanciato, ma è stato Allah a lanciare»."),
"sira_166": ("Come descrive il Corano lo stato di alcuni credenti alla partenza per Badr?", ["Ne discutevano come se fossero condotti alla morte", "Erano tutti impazienti", "Rifiutarono di partire", "Chiesero un rinvio"], "«Discutevano con te sulla verità dopo che si era manifestata, come se fossero condotti alla morte»."),
"sira_167": ("Come ricorda il Corano ai credenti la loro condizione prima della vittoria?", ["Erano pochi e oppressi sulla terra, poi Allah diede loro rifugio e soccorso", "Erano ricchi", "Erano numerosi", "Già governavano"], "«Ricordate quando eravate pochi e oppressi sulla terra… Egli vi diede rifugio e vi sostenne con il Suo soccorso»."),
"sira_168": ("Quale compagno propose a Badr di spostare l'esercito al pozzo più vicino al nemico?", ["Al-Hubab ibn al-Mundhir", "Sa'd ibn Mu'adh", "Al-Miqdad", "Az-Zubayr"], "Al-Hubab ibn al-Mundhir chiese se la posizione venisse dalla rivelazione o dal parere; saputo che era un parere, propose di avanzare fino al pozzo, e il Profeta ﷺ accettò."),
"sira_169": ("Qual era il nome del punto d'acqua presso il quale si svolse la battaglia di Badr?", ["Badr, un pozzo sulla via delle carovane", "Zamzam", "Quba", "Al-Hudaybiyya"], "Badr era un punto d'acqua sulla via carovaniera tra la Mecca e la Siria; la battaglia ne prese il nome."),
"sira_170": ("Quale questione relativa ai prigionieri fu trattata dalla rivelazione dopo Badr?", ["Il riscatto accettato per i prigionieri", "La spartizione dell'acqua", "La scelta dell'accampamento", "La data del ritorno"], "Il passo parla dei prigionieri e del riscatto, poi permette ciò che era stato preso come lecito e buono."),
"sira_171": ("Secondo la sura Al 'Imran, che cosa rovesciò la situazione a Uhud dopo un primo successo?", ["La disobbedienza e la disputa sull'ordine ricevuto", "Il numero del nemico", "Il caldo", "La mancanza d'acqua"], "«…finché vi perdeste d'animo, disputaste sull'ordine e disobbediste»."),
"sira_172": ("Che cosa dice il Corano di coloro che sono uccisi sulla via di Allah?", ["Non crederli morti: sono vivi presso il loro Signore", "Dormono fino all'Ultimo Giorno", "Ritornano", "Sono dimenticati"], "«Non considerare morti coloro che sono stati uccisi sulla via di Allah: sono invece vivi presso il loro Signore e ben provvisti»."),
"sira_173": ("Su quale collina il Profeta ﷺ collocò gli arcieri a Uhud?", ["Il monte degli Arcieri (Jabal ar-Rumat)", "Il monte Safa", "Il monte Thawr", "Il monte Hira"], "Cinquanta arcieri furono collocati su una collina poi chiamata «il monte degli arcieri», con l'ordine di non lasciarla."),
"sira_174": ("Come descrive la sura Al-Ahzab la prova dell'assedio di Medina?", ["Gli sguardi si smarrirono e i cuori salirono alle gole", "La città cadde", "Mancarono solo i viveri", "Il cielo si oscurò"], "«Quando vennero a voi dall'alto e dal basso, e quando gli sguardi si smarrirono e i cuori salirono alle gole»."),
"sira_175": ("Come descrive il Corano l'esito della battaglia del Fossato?", ["Allah respinse i coalizzati pieni di rabbia, senza che ottenessero alcun bene", "Una lunga battaglia campale", "Un trattato di pace", "Una ritirata dei musulmani"], "«E Allah respinse i miscredenti pieni di rabbia: non ottennero alcun bene, e Allah bastò ai credenti nel combattimento»."),
"sira_176": ("Dove si trova Hudaybiyya, luogo del famoso trattato?", ["Al limite del territorio sacro, a ovest della Mecca", "Vicino a Medina", "Nello Yemen", "In Siria"], "Hudaybiyya è un luogo ai confini del territorio sacro della Mecca, dove fu concluso il trattato."),
"sira_177": ("Quale visione del Profeta ﷺ conferma il Corano dopo Hudaybiyya?", ["Che sarebbero entrati nella Moschea Sacra in sicurezza, con il capo rasato o i capelli accorciati", "Che avrebbero vinto a Khaybar", "Che avrebbero costruito una città", "Che sarebbero andati in Siria"], "«Allah ha avverato la visione del Suo Messaggero: entrerete nella Moschea Sacra in tutta sicurezza»."),
"sira_178": ("Che cosa ricorda la sura Al-Fath riguardo alle mani trattenute alla Mecca?", ["Allah trattenne le loro mani da voi e le vostre da loro nella valle della Mecca", "Ordinò di combattere", "Chiuse le strade", "Mandò una tempesta"], "«Ed è Lui che, nella valle della Mecca, trattenne le loro mani da voi e le vostre mani da loro, dopo avervi dato la vittoria su di loro»."),
"sira_179": ("In quale anno dell'Egira ebbe luogo la spedizione di Khaybar?", ["Il settimo", "Il secondo", "Il quinto", "Il decimo"], "Khaybar ebbe luogo nell'anno 7 dell'Egira, l'anno successivo al trattato di Hudaybiyya."),
"sira_180": ("Come si chiama la 'umra compiuta l'anno dopo Hudaybiyya, secondo i termini del trattato?", ["'Umrat al-Qada", "Hijjat al-Wada'", "'Umrat al-Ji'rana", "Al-Hajj al-Akbar"], "Il trattato prevedeva che i musulmani tornassero l'anno seguente; quella 'umra si chiama 'umrat al-qada."),
"sira_181": ("Quale sovrano stracciò la lettera del Profeta ﷺ ricevendola?", ["Il re di Persia (Cosroe)", "Il Negus d'Abissinia", "Il governatore del Bahrein", "Il re dello Yemen"], "Il Profeta ﷺ inviò lettere ai sovrani vicini; quella indirizzata al re di Persia fu stracciata."),
"sira_182": ("Quale compagno portò la lettera del Profeta ﷺ al Negus d'Abissinia e ad altri sovrani?", ["'Amr ibn Umayya ad-Damri", "Abu Hurayra", "Anas ibn Malik", "Ubayy ibn Ka'b"], "Furono scelti messaggeri tra i compagni; 'Amr ibn Umayya ad-Damri fu inviato al Negus."),
"sira_183": ("In quale direzione si trova Khaybar rispetto a Medina?", ["A nord", "A sud", "A est", "A ovest, sul mare"], "Khaybar è un'oasi fortificata a nord di Medina, sulla via della Siria."),
"sira_184": ("Che cosa divenne la casa di Abu Sufyan il giorno della conquista della Mecca?", ["Un luogo sicuro per chi vi entrava", "Una prigione", "Un magazzino", "Una moschea"], "Il Profeta ﷺ dichiarò al sicuro chi entrasse nella Moschea Sacra, restasse in casa propria o entrasse nella casa di Abu Sufyan."),
"sira_185": ("Quale anno è chiamato «l'anno della conquista» ('am al-fath)?", ["L'anno 8 dell'Egira", "L'anno 6 dell'Egira", "L'anno 10 dell'Egira", "L'anno 2 dell'Egira"], "La Mecca fu conquistata nell'anno 8 dell'Egira, noto come l'anno della conquista."),
"sira_186": ("Quale battaglia seguì poco dopo la conquista della Mecca, contro le tribù degli Hawazin?", ["Hunayn", "Badr", "Uhud", "Khaybar"], "Hunayn ebbe luogo poco dopo la conquista, in una valle tra la Mecca e Ta'if."),
"sira_187": ("Che cosa fece scendere Allah sul Suo Messaggero ﷺ e sui credenti dopo il loro smarrimento a Hunayn?", ["La Sua quiete (sakina) e schiere che non vedevano", "La pioggia", "Un vento", "Un rinforzo di cavalieri"], "«Poi Allah fece scendere la Sua quiete sul Suo Messaggero e sui credenti, e fece scendere schiere che non vedevate»."),
"sira_188": ("Verso quale città si diresse l'esercito musulmano dopo Hunayn?", ["Ta'if", "Khaybar", "Tabuk", "Sana'a"], "Dopo Hunayn i musulmani assediarono Ta'if, i cui abitanti si erano trincerati."),
"sira_189": ("Quale spedizione chiama il Corano «l'ora della difficoltà» (sa'at al-'usra)?", ["Tabuk", "Badr", "Khaybar", "Hunayn"], "«Allah ha accolto il pentimento del Profeta, degli emigrati e degli ausiliari che lo seguirono nell'ora della difficoltà»."),
"sira_190": ("Che cosa dice il Corano dei tre compagni rimasti indietro a Tabuk, prima del loro perdono?", ["La terra parve loro angusta nonostante la sua ampiezza, poi Allah accolse il loro pentimento", "Furono banditi", "Partirono per lo Yemen", "Furono dimenticati"], "«E ai tre che furono lasciati indietro: finché la terra, con tutta la sua ampiezza, divenne angusta per loro… poi Egli accolse il loro pentimento»."),
"sira_191": ("In quale direzione si trova Tabuk, meta dell'ultima grande spedizione?", ["A nord, verso il confine della Siria", "A sud, verso lo Yemen", "A est, verso l'Iraq", "A ovest, sul Mar Rosso"], "Tabuk è a nord di Medina, sulla via della Siria; fu l'ultima grande spedizione del Profeta ﷺ."),
"sira_192": ("Quale compagno equipaggiò gran parte dell'esercito di Tabuk con i propri beni?", ["'Uthman ibn 'Affan", "Sa'd ibn Abi Waqqas", "Talha ibn 'Ubaydillah", "Abu Dharr"], "'Uthman ibn 'Affan fornì una parte considerevole dell'equipaggiamento dell'«esercito della difficoltà» (jaysh al-'usra)."),
"sira_193": ("Quale compagno fu il primo a scagliare una freccia sulla via di Allah?", ["Sa'd ibn Abi Waqqas", "Az-Zubayr ibn al-'Awwam", "Talha ibn 'Ubaydillah", "Abu 'Ubayda"], "Sa'd ibn Abi Waqqas, tra i primissimi convertiti, è noto come il primo ad aver scagliato una freccia sulla via di Allah."),
"sira_194": ("Quale compagno è chiamato «il discepolo (hawari) del Messaggero di Allah ﷺ»?", ["Az-Zubayr ibn al-'Awwam", "Abu Hurayra", "Salman al-Farisi", "Bilal"], "Az-Zubayr ibn al-'Awwam, cugino del Profeta ﷺ, fu chiamato il suo hawari, il suo sostegno più vicino."),
"sira_195": ("A quale compagno fu affidata la conoscenza degli ipocriti, tanto da essere detto «il custode del segreto»?", ["Hudhayfa ibn al-Yaman", "Abu Musa al-Ash'ari", "'Ammar ibn Yasir", "Abu ad-Darda"], "Hudhayfa ibn al-Yaman è noto come «sahib as-sirr», colui a cui il Profeta ﷺ confidò ciò che sapeva degli ipocriti."),
"sira_196": ("Da quale terra veniva Salman, detto «al-Farisi», che propose il fossato?", ["Dalla Persia", "Dallo Yemen", "Dall'Abissinia", "Da Bisanzio"], "Salman, di origine persiana, cercò a lungo la verità prima di raggiungere il Profeta ﷺ a Medina."),
"sira_197": ("Quale donna, madre di Anas ibn Malik, offrì al Profeta ﷺ il servizio del proprio figlio?", ["Umm Sulaym", "Umm Salama", "Umm Ayman", "Umm Habiba"], "Umm Sulaym, degli Ansar, presentò suo figlio Anas al Profeta ﷺ perché lo servisse al suo arrivo a Medina."),
"sira_198": ("Quale moglie del Profeta ﷺ fu nota per la sua grande dottrina e trasmise numerosi hadith?", ["'A'isha", "Sawda", "Juwayriya", "Maymuna"], "'A'isha, figlia di Abu Bakr, è tra le più grandi trasmettitrici di hadith e un riferimento nella scienza religiosa."),
"sira_199": ("Quale moglie del Profeta ﷺ era sua cugina, e il cui matrimonio è menzionato nella sura Al-Ahzab?", ["Zaynab bint Jahsh", "Hafsa", "Umm Salama", "Safiyya"], "Il matrimonio con Zaynab bint Jahsh è menzionato nella sura Al-Ahzab (33:37)."),
"sira_200": ("Quale moglie del Profeta ﷺ consigliò il gesto che sbloccò la crisi di Hudaybiyya?", ["Umm Salama", "'A'isha", "Hafsa", "Zaynab bint Jahsh"], "Umm Salama consigliò al Profeta ﷺ di uscire e compiere lui stesso il sacrificio e la rasatura: i compagni lo seguirono subito."),
"sira_201": ("Qual è il nome completo del Profeta ﷺ, fino a suo nonno?", ["Muhammad ibn 'Abdillah ibn 'Abd al-Muttalib", "Muhammad ibn Abi Talib", "Muhammad ibn al-'Abbas", "Muhammad ibn Hashim"], "Egli è Muhammad, figlio di 'Abdullah, figlio di 'Abd al-Muttalib, della tribù dei Quraysh."),
"sira_202": ("Quale altro nome del Profeta ﷺ, menzionato nel Corano da 'Isa, significa «il più degno di lode»?", ["Ahmad", "Al-Mustafa", "Al-Amin", "Abu-l-Qasim"], "'Isa annunciò un messaggero dopo di lui «il cui nome sarà Ahmad» (Corano 61:6)."),
"sira_203": ("Quanto durò la rivelazione del Corano al Profeta ﷺ?", ["Circa ventitré anni", "Dieci anni", "Quarant'anni", "Una sola notte"], "La rivelazione si estese per circa ventitré anni: tredici alla Mecca e dieci a Medina."),
"sira_204": ("Quale compagno fu il primo uomo libero e adulto ad abbracciare l'islam?", ["Abu Bakr as-Siddiq", "'Umar ibn al-Khattab", "'Uthman ibn 'Affan", "Sa'd ibn Abi Waqqas"], "Tra gli uomini liberi e adulti, Abu Bakr fu il primo a rispondere all'appello del Profeta ﷺ."),
"sira_205": ("Quale bambino fu il primo ad abbracciare l'islam?", ["'Ali ibn Abi Talib", "Anas ibn Malik", "Usama ibn Zayd", "'Abdullah ibn 'Umar"], "'Ali ibn Abi Talib, cresciuto nella casa del Profeta ﷺ, fu il primo dei bambini a credere."),
"sira_206": ("Quale liberto del Profeta ﷺ fu il primo tra i liberti ad abbracciare l'islam?", ["Zayd ibn Haritha", "Bilal ibn Rabah", "Suhayb ar-Rumi", "Salman al-Farisi"], "Zayd ibn Haritha, affrancato e cresciuto come un figlio dal Profeta ﷺ, fu il primo dei liberti a credere."),
"sira_207": ("Quale versetto pose fine all'adozione giuridica, dicendo che il Profeta ﷺ non è padre di alcuno dei loro uomini?", ["«Muhammad non è padre di alcuno dei vostri uomini, ma è il Messaggero di Allah e il sigillo dei profeti»", "«Chiamateli con il nome dei loro padri»", "«I legami di sangue prevalgono»", "«Non adottate»"], "«Muhammad non è padre di alcuno dei vostri uomini, ma è il Messaggero di Allah e l'ultimo dei profeti»."),
"sira_208": ("In quale giorno della settimana i musulmani si riuniscono per la preghiera comunitaria istituita a Medina?", ["Il venerdì", "Il sabato", "La domenica", "Il lunedì"], "La preghiera del venerdì (al-jumu'a) fu istituita a Medina e riunisce la comunità ogni settimana."),
"sira_209": ("Quale compagno diresse la preghiera durante l'ultima malattia del Profeta ﷺ, per suo ordine?", ["Abu Bakr as-Siddiq", "'Umar ibn al-Khattab", "'Ali ibn Abi Talib", "Bilal"], "Il Profeta ﷺ ordinò che Abu Bakr dirigesse la preghiera durante la sua malattia; i compagni vi videro un segno."),
"sira_210": ("Quale califfo fu colpito a morte mentre dirigeva la preghiera dell'alba?", ["'Umar ibn al-Khattab", "Abu Bakr", "'Ali ibn Abi Talib", "Mu'awiya"], "'Umar ibn al-Khattab fu colpito durante la preghiera del fajr a Medina e morì per le ferite."),
"sira_211": ("Quanto durò il califfato di Abu Bakr?", ["Circa due anni", "Dieci anni", "Vent'anni", "Trent'anni"], "Abu Bakr governò circa due anni prima della sua morte, e 'Umar gli succedette."),
"sira_212": ("Contro quale movimento dovette agire Abu Bakr all'inizio del suo califfato?", ["Il rifiuto della zakat e l'apostasia di alcune tribù", "Un'invasione dalla Persia", "Una carestia", "Una rivolta a Medina"], "Il primo califfato si aprì con le cosiddette guerre della ridda, contro le tribù che rifiutarono la zakat o lasciarono l'islam."),
"sira_213": ("Quale titolo adottò 'Umar ibn al-Khattab come capo della comunità?", ["Amir al-Mu'minin (comandante dei credenti)", "Sultano", "Malik", "Imam al-Haramayn"], "Il titolo di amir al-mu'minin si affermò con 'Umar e fu portato dai califfi dopo di lui."),
"sira_214": ("Quale moschea di Gerusalemme fu la prima qibla dei musulmani?", ["La moschea di Al-Aqsa", "La moschea di Quba", "La moschea del Profeta ﷺ", "La Moschea Sacra"], "I musulmani pregarono dapprima verso Gerusalemme, prima che la qibla fosse fissata verso la Ka'ba."),
"sira_215": ("Quali sono le tre moschee verso cui il viaggio è particolarmente raccomandato?", ["La Moschea Sacra, la moschea del Profeta ﷺ e Al-Aqsa", "Quba, Al-Aqsa e Kufa", "La Moschea Sacra, Quba e Damasco", "Al-Aqsa, Kufa e Bassora"], "Il viaggio è particolarmente raccomandato verso tre moschee: la Moschea Sacra, la moschea del Profeta ﷺ e la moschea di Al-Aqsa."),
"sira_216": ("Dove pronunciò il Profeta ﷺ il suo sermone d'addio, il giorno di 'Arafa?", ["Nella valle di 'Urana, sul monte 'Arafat", "A Mina", "Davanti alla Ka'ba", "A Muzdalifa"], "Il sermone d'addio fu pronunciato il giorno di 'Arafa, nella valle di 'Urana ai piedi del monte 'Arafat."),
"sira_217": ("Che cosa dichiarò inviolabile il Profeta ﷺ nel suo sermone d'addio?", ["Il sangue, i beni e l'onore di ciascuno", "Le vie commerciali", "I pozzi di Medina", "I palmeti"], "Dichiarò sacri il sangue, i beni e l'onore dei musulmani, come sono sacri quel giorno, quel mese e quella città."),
"sira_218": ("Che cosa lasciò il Profeta ﷺ alla sua comunità, secondo il sermone d'addio, perché non si smarrisse?", ["Il Libro di Allah", "Un tesoro", "Un esercito", "Una mappa"], "Ricordò loro che lasciava tra loro ciò a cui aggrapparsi per non smarrirsi: il Libro di Allah."),
"sira_219": ("In quale mese del calendario musulmano si compie il pellegrinaggio, compiuto dal Profeta ﷺ nel suo addio?", ["Dhul-Hijja", "Ramadan", "Muharram", "Rajab"], "Il pellegrinaggio d'addio ebbe luogo in Dhul-Hijja dell'anno 10 dell'Egira."),
"sira_220": ("Chi lavò e avvolse il corpo del Profeta ﷺ dopo la sua morte?", ["I membri della sua famiglia, tra cui 'Ali e al-'Abbas", "Solo gli Ansar", "Bilal e Anas", "La gente di Quba"], "Se ne occupò la sua stessa famiglia, tra cui 'Ali ibn Abi Talib e suo zio al-'Abbas."),
"sira_221": ("In quale mese dell'anno egiriano morì il Profeta ﷺ?", ["Rabi' al-Awwal", "Ramadan", "Shawwal", "Dhul-Qa'da"], "Il Profeta ﷺ morì a Medina nel mese di Rabi' al-Awwal dell'anno 11 dell'Egira."),
"sira_222": ("Quale versetto recitò Abu Bakr per ricordare che il Profeta ﷺ era mortale?", ["«Muhammad non è che un messaggero; altri messaggeri sono passati prima di lui»", "«Ti abbiamo inviato come misericordia»", "«Sei di sublime carattere»", "«Quando giunge il soccorso di Allah»"], "«Muhammad non è che un messaggero; altri messaggeri sono passati prima di lui. Se morisse o venisse ucciso, tornereste sui vostri passi?»"),
"sira_223": ("Quale compagno è noto soprattutto per la quantità di hadith che memorizzò?", ["Abu Hurayra", "Anas ibn Malik", "Jabir ibn 'Abdillah", "Abu Sa'id al-Khudri"], "Abu Hurayra trascorse gli ultimi anni della vita del Profeta ﷺ al suo fianco e divenne il più prolifico trasmettitore di hadith."),
"sira_224": ("Quale compagno, cugino del Profeta ﷺ, divenne la grande autorità dell'esegesi coranica?", ["'Abdullah ibn 'Abbas", "'Abdullah ibn 'Umar", "'Abdullah ibn Mas'ud", "'Abdullah ibn az-Zubayr"], "'Abdullah ibn 'Abbas, per cui il Profeta ﷺ invocò la comprensione del Libro, fu chiamato «l'interprete del Corano»."),
"sira_225": ("Quale compagno fu inviato dal Profeta ﷺ come governatore e giudice nello Yemen, e morì giovane in Siria?", ["Mu'adh ibn Jabal", "Abu 'Ubayda ibn al-Jarrah", "'Amr ibn al-'As", "Khalid ibn al-Walid"], "Mu'adh ibn Jabal, dotto tra i compagni, fu inviato nello Yemen e morì poi in Siria ancora giovane."),
"sira_226": ("Quale valle si estende tra le due colline di Safa e Marwa, percorse durante il pellegrinaggio?", ["La valle della Mecca, attorno alla Ka'ba", "La valle di 'Urana", "La valle di Mina", "La valle di Badr"], "Safa e Marwa sono due piccole colline della valle della Mecca, oggi incluse nel recinto della Moschea Sacra."),
"sira_227": ("Quali due grandi tribù arabe di Medina si facevano guerra prima dell'arrivo del Profeta ﷺ?", ["Gli Aws e i Khazraj", "Quraysh e Hawazin", "Thaqif e Kinana", "Tamim e Bakr"], "Gli Aws e i Khazraj, a lungo nemici, formarono insieme gli Ansar dopo l'arrivo del Profeta ﷺ."),
"sira_228": ("Quale versetto ricorda agli Ansar che erano nemici e che Allah unì i loro cuori?", ["«Eravate nemici, ed Egli riconciliò i vostri cuori»", "«Eravate poveri»", "«Eravate pochi»", "«Eravate smarriti»"], "«Ricordate la grazia di Allah su di voi: eravate nemici ed Egli riconciliò i vostri cuori; per Sua grazia siete divenuti fratelli»."),
"sira_229": ("Come loda il Corano gli Ansar nella loro accoglienza degli emigrati?", ["Preferiscono gli altri a se stessi, anche essendo nel bisogno", "Vendettero loro delle terre", "Prestarono loro del denaro", "Li alloggiarono fuori città"], "«E li preferiscono a se stessi, anche essendo nel bisogno. Chi si preserva dalla propria avarizia, quelli sono i vincenti»."),
"sira_230": ("Come si chiama l'insieme delle parole, degli atti e delle approvazioni del Profeta ﷺ?", ["La Sunna", "Il Corano", "La Sira", "Il Tafsir"], "La Sunna è ciò che il Profeta ﷺ disse, fece o approvò; la Sira è il racconto della sua vita."),
"sira_231": ("Come si chiama la generazione che seguì quella dei compagni?", ["I Tabi'un (i seguaci)", "Gli Ansar", "I Muhajirun", "I Qurra'"], "I Tabi'un sono coloro che incontrarono i compagni senza aver visto il Profeta ﷺ."),
"sira_232": ("Come si chiama la catena dei trasmettitori di un hadith?", ["L'isnad", "Il matn", "Il tafsir", "Il tajwid"], "L'isnad è la catena di trasmissione; il matn è il testo stesso dell'hadith."),
"sira_233": ("Quali due raccolte di hadith sono ritenute le più rigorose, dette «i due Sahih»?", ["Sahih al-Bukhari e Sahih Muslim", "I Sunan di Abu Dawud e at-Tirmidhi", "Il Muwatta' e il Musnad", "I Sunan di an-Nasa'i e Ibn Maja"], "Sahih al-Bukhari e Sahih Muslim sono chiamati insieme «i due Sahih» (as-sahihan)."),
"sira_234": ("In quale città si trovano la moschea del Profeta ﷺ e la sua tomba?", ["Medina", "La Mecca", "Gerusalemme", "Ta'if"], "La moschea del Profeta ﷺ e la sua tomba si trovano a Medina, la città dell'Egira."),
"sira_235": ("Quale epiteto porta Medina, in rapporto alla luce che le viene attribuita?", ["Al-Madina al-Munawwara (la città illuminata)", "Umm al-Qura", "Dar as-Salam", "Al-Mada'in"], "Medina è chiamata al-Munawwara; la Mecca, invece, è chiamata al-Mukarrama."),
"sira_236": ("Quale nome dà il Corano alla Mecca, «la madre delle città»?", ["Umm al-Qura", "Al-Madina", "Al-Balad al-Amin", "Bakka"], "«…affinché tu avverta la madre delle città (Umm al-Qura) e coloro che le stanno attorno»."),
"sira_237": ("Qual era il mestiere di Khadija, prima moglie del Profeta ﷺ?", ["Commerciante", "Medico", "Poetessa", "Tessitrice"], "Khadija bint Khuwaylid era una commerciante rispettata della Mecca, che affidò la sua carovana al giovane Muhammad ﷺ."),
"sira_238": ("Per quanto tempo il Profeta ﷺ restò sposato alla sola Khadija?", ["Fino alla sua morte; non sposò altre donne mentre lei era in vita", "Due anni", "Cinque anni", "Ne sposò altre subito"], "Il Profeta ﷺ non sposò alcuna altra donna mentre Khadija era in vita; gli altri matrimoni vennero dopo la sua morte."),
"sira_239": ("Come si chiama lo zio del Profeta ﷺ che lo protesse senza abbracciare l'islam?", ["Abu Talib", "Hamza", "Al-'Abbas", "Abu Lahab"], "Abu Talib, padre di 'Ali, protesse suo nipote contro i Quraysh fino alla sua morte."),
"sira_240": ("Quale zio del Profeta ﷺ fu fatto prigioniero a Badr prima di abbracciare l'islam?", ["Al-'Abbas ibn 'Abd al-Muttalib", "Abu Talib", "Hamza", "Az-Zubayr ibn 'Abd al-Muttalib"], "Al-'Abbas, zio del Profeta ﷺ e capostipite degli Abbasidi, fu catturato a Badr e poi abbracciò l'islam."),
"sira_241": ("Come si chiamano i compagni che parteciparono alla battaglia di Badr?", ["I Badriyyun (la gente di Badr)", "Gli Ansar", "I Muhajirun", "Gli Uhudiyyun"], "I compagni presenti a Badr sono detti Badriyyun, e quel merito è loro proprio."),
"sira_242": ("Quale parte del bottino riserva il Corano ad Allah, al Messaggero, ai parenti, agli orfani, ai poveri e al viandante?", ["Il quinto", "La metà", "Il decimo", "Il terzo"], "«Sappiate che di ogni bottino che prendete, un quinto spetta ad Allah, al Messaggero, ai parenti, agli orfani, ai poveri e al viandante»."),
"sira_243": ("Quale versetto, associato al sermone d'addio, fonda l'uguaglianza dei popoli davanti ad Allah?", ["«Il più nobile tra voi presso Allah è il più timorato»", "«Gli uomini vengono da un solo padre»", "«Nessuno porta il fardello altrui»", "«Nessuna costrizione nella religione»"], "«O uomini, vi abbiamo creati da un maschio e una femmina… il più nobile tra voi presso Allah è il più timorato»."),
"sira_244": ("Quante persone parteciparono al secondo patto di 'Aqaba, l'incontro decisivo con la gente di Yathrib?", ["Una delegazione di più di settanta persone", "Tre", "Dieci", "Cinquecento"], "Il secondo patto di 'Aqaba riunì una delegazione di più di settanta uomini e donne di Yathrib."),
"sira_245": ("Quanti naqib (responsabili) fece designare il Profeta ﷺ tra la gente di Yathrib al patto di 'Aqaba?", ["Dodici", "Quattro", "Sette", "Venti"], "Furono scelti dodici naqib per rappresentare i gruppi della delegazione di Yathrib e rispondere del loro impegno."),
"sira_246": ("Quale nome assunse Medina dopo l'Egira?", ["Madinat an-Nabi, la città del Profeta ﷺ", "Yathrib", "Solo Tayba", "Al-Qura"], "Yathrib prese il nome di Madinat an-Nabi, «la città del Profeta ﷺ», abbreviato in al-Madina."),
"sira_247": ("Quale califfo fece copiare il Corano in esemplari ufficiali inviati alle province?", ["'Uthman ibn 'Affan", "Abu Bakr", "'Umar", "'Ali"], "Abu Bakr fece raccogliere il testo; 'Uthman fece redigere copie ufficiali e le inviò alle grandi città."),
"sira_248": ("In quale lingua fu rivelato il Corano al Profeta ﷺ?", ["In arabo", "In aramaico", "In persiano", "In greco"], "Il Corano fu rivelato in lingua araba chiara, quella del popolo stesso del Profeta ﷺ."),
"sira_249": ("Quale compagno fu inviato dal Profeta ﷺ nel Bahrein, tornandone con il tributo?", ["Abu 'Ubayda ibn al-Jarrah", "Bilal", "Anas ibn Malik", "Abu Dharr"], "Abu 'Ubayda ibn al-Jarrah, detto «l'uomo di fiducia di questa comunità», tornò dal Bahrein con il tributo."),
"sira_250": ("Quale evento segna l'inizio del calendario musulmano?", ["L'Egira dalla Mecca a Medina", "La nascita del Profeta ﷺ", "La prima rivelazione", "La conquista della Mecca"], "Il calendario egiriano comincia con l'anno dell'Egira, decisione presa durante il califfato di 'Umar."),
}
